import { UserSchema } from "/tmp/token-saver-runs/red-V1-defective-delegate-1/src/models/user.schema";
const d = new Date();
const base = { id: "1", name: "A", createdAt: d, updatedAt: d };
console.log("valid:", UserSchema.safeParse({ ...base, email: "a@b.co" }).success);
console.log("invalid:", UserSchema.safeParse({ ...base, email: "nope" }).success);
EOF
cp /tmp/us.test.ts ./_check.ts && npx tsx ./_check.ts 2>&1 || node --experimental-strip-types ./_check.ts; rm -f ./_check.ts

